package com.profa.security;import jakarta.servlet.*;import jakarta.servlet.http.*;import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;import org.springframework.security.core.authority.SimpleGrantedAuthority;import org.springframework.security.core.context.SecurityContextHolder;import org.springframework.stereotype.Component;import java.io.IOException;import java.util.*;@Component public class JwtFilter implements Filter{final JwtService jwt;public JwtFilter(JwtService j){jwt=j;}public void doFilter(ServletRequest req,ServletResponse res,FilterChain chain)throws IOException,ServletException{HttpServletRequest r=(HttpServletRequest)req;String h=r.getHeader("Authorization");if(h!=null&&h.startsWith("Bearer "))try{var c=jwt.parse(h.substring(7)).getPayload();var auth=new UsernamePasswordAuthenticationToken(c.getSubject(),null,List.of(new SimpleGrantedAuthority("ROLE_"+c.get("role",String.class))));SecurityContextHolder.getContext().setAuthentication(auth);}catch(Exception ignored){}chain.doFilter(req,res);}}